import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { Image, ImageStyle, StyleProp, View, ViewStyle } from 'react-native'
import { SvgUri } from 'react-native-svg'

import SkeletonLoader from '@common/components/SkeletonLoader'
import { SkeletonLoaderProps } from '@common/components/SkeletonLoader/types'
import { isMobile } from '@common/config/env'
import useTheme from '@common/hooks/useTheme'
import commonStyles from '@common/styles/utils/common'
import flexboxStyles from '@common/styles/utils/flexbox'

type Props = {
  uri?: string
  uris?: string[]
  fallback?: () => any
  size: ViewStyle['width']
  isRound?: boolean
  iconScale?: number
  containerStyle?: StyleProp<ViewStyle>
  imageStyle?: ImageStyle
  skeletonAppearance?: SkeletonLoaderProps['appearance']
  hideOnError?: boolean
}

const ManifestImage = ({
  uri,
  uris = [],
  fallback,
  size = 64,
  isRound,
  iconScale = 1,
  containerStyle = {},
  imageStyle = {},
  skeletonAppearance,
  hideOnError = false
}: Props) => {
  const { theme } = useTheme()

  const [isLoading, setIsLoading] = useState(true)
  const [hasError, setHasError] = useState(false)
  const [currentUri, setCurrentUri] = useState({
    index: 0,
    uri: uri || uris[0]
  })
  const scaledSize = typeof size === 'number' ? size * iconScale : size
  const roundBorderRadius = typeof scaledSize === 'number' ? scaledSize / 2 : 50
  const svgSize = typeof scaledSize === 'number' ? scaledSize : '100%'

  // React Native's Image can't render SVGs, so on mobile they go through SvgUri
  const shouldRenderAsSvg = useMemo(() => {
    if (!isMobile) return false

    const lowercasedUri = currentUri.uri?.toLowerCase()

    return !!lowercasedUri && (lowercasedUri.endsWith('.svg') || lowercasedUri.includes('.svg?'))
  }, [currentUri.uri])

  const onError = useCallback(() => {
    setHasError(true)
    // Unlike Image's onLoadEnd, SvgUri's onLoad doesn't fire on failure,
    // so without this the skeleton would hide the fallback forever
    setIsLoading(false)

    if (uris.length && uris.length > 1 && currentUri.index < uris.length - 1) {
      setCurrentUri({
        index: currentUri.index + 1,
        uri: uris[currentUri.index + 1]
      })
    }
  }, [currentUri.index, uris])

  const onLoadEnd = useCallback(() => {
    setIsLoading(false)
  }, [])

  useEffect(() => {
    if (!uris.length && !uri) {
      setIsLoading(false)
      setHasError(true)
      return
    }

    setCurrentUri({ index: 0, uri: uri || uris[0] })
    setHasError(false)
    setIsLoading(true)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [uri, uris?.length])

  if (hideOnError && !isLoading && hasError && !fallback) return null

  return (
    <View
      style={[
        flexboxStyles.alignCenter,
        flexboxStyles.justifyCenter,
        commonStyles.borderRadiusPrimary,
        commonStyles.hidden,
        !!isRound && { borderRadius: roundBorderRadius },
        { width: size, height: size },
        containerStyle
      ]}
    >
      {isLoading && (
        <SkeletonLoader
          width={scaledSize}
          height={scaledSize}
          style={{
            position: 'absolute',
            zIndex: 3
          }}
          appearance={skeletonAppearance}
        />
      )}
      {!isLoading && hasError && !!fallback && fallback()}
      {!!currentUri.uri && !hasError && shouldRenderAsSvg && (
        <SvgUri
          uri={currentUri.uri}
          width={svgSize}
          height={svgSize}
          onError={onError}
          onLoad={onLoadEnd}
          style={{ opacity: isLoading ? 0 : 1 }}
        />
      )}
      {!!currentUri.uri && !hasError && !shouldRenderAsSvg && (
        <Image
          source={{ uri: currentUri.uri }}
          onError={onError}
          onLoadEnd={onLoadEnd}
          resizeMode="contain"
          style={[
            {
              height: scaledSize,
              width: scaledSize,
              backgroundColor: theme.primaryBackground,
              opacity: isLoading ? 0 : 1
            },
            !!isRound && { borderRadius: roundBorderRadius },
            imageStyle
          ]}
        />
      )}
    </View>
  )
}

export default React.memo(ManifestImage)
